package ramsql

import (
	"database/sql"
	"testing"
)

// TestCreateIndexSortOrderAndPartial checks that indexes using per-column sort order and a partial
// predicate (as generated by GORM for e.g. `index:name,sort:desc,where:x IS NULL`) are accepted
// and do not change query results.
func TestCreateIndexSortOrderAndPartial(t *testing.T) {
	db, err := sql.Open("ramsql", "TestCreateIndexSortOrderAndPartial")
	if err != nil {
		t.Fatalf("sql.Open: %s", err)
	}
	defer db.Close()

	for _, q := range []string{
		`CREATE TABLE results (id TEXT PRIMARY KEY, control_id TEXT, parent_control_id TEXT, ts INT)`,
		`CREATE INDEX idx_sorted ON results (control_id, ts DESC, id DESC)`,
		`CREATE INDEX idx_partial ON results (control_id, ts DESC) WHERE parent_control_id IS NULL`,
		`INSERT INTO results (id, control_id, parent_control_id, ts) VALUES ('a', 'c1', NULL, 1)`,
		`INSERT INTO results (id, control_id, parent_control_id, ts) VALUES ('b', 'c1', 'p', 2)`,
	} {
		if _, err := db.Exec(q); err != nil {
			t.Fatalf("%s: %s", q, err)
		}
	}

	var n int
	if err := db.QueryRow(`SELECT COUNT(*) FROM results WHERE parent_control_id IS NULL`).Scan(&n); err != nil {
		t.Fatal(err)
	}
	if n != 1 {
		t.Fatalf("expected 1 row, got %d", n)
	}
	if err := db.QueryRow(`SELECT COUNT(*) FROM results WHERE control_id = 'c1'`).Scan(&n); err != nil {
		t.Fatal(err)
	}
	if n != 2 {
		t.Fatalf("expected 2 rows, got %d", n)
	}
}
